#!/usr/bin/env python3
"""Generates docs/ALA_HAZRAT_DOSSIER_DRAFT.md and supabase/content/ala_hazrat_draft.sql from content/ala-hazrat.json (single source of truth)."""
import json
d=json.load(open('content/ala-hazrat.json', encoding='utf-8')); S={s['id']:s for s in d['sources']}
q=lambda v:"null" if v is None else "'"+str(v).replace("'","''")+"'"
evidence_tier=lambda sid: {'academic_research':'academic_research','community_devotional':'community_devotional','primary_source':'primary','reference_work':'contemporary_account','historical_newspaper':'contemporary_account'}.get(S[sid]['tier'],'community_devotional')
loc=lambda cl:"; ".join(f"{x['id']} {x['locator'] or 'locator not verified'}" for x in cl['sources']) or "no source attached"
md=["# Imam Ahmad Raza Khan (Ala Hazrat): research dossier (DRAFT, in review)","",
"> **Status: draft.** Nothing here is VERIFIED. The astronomy-work investigation relies primarily on S1 (one 2023 journal article); biographical context now also draws on S4 (Usha Sanyal, 2005) and S6 (1998). Each claim carries its own label; exact dates, editions, and primary Urdu passages remain subject to review. Generated from `content/ala-hazrat.json`.","",
"## How to read","Labels: ACADEMICALLY SUPPORTED = one academic source reports it; UNDER REVIEW = incomplete evidence; UNVERIFIED = only community/tradition or no source; MODERN SCIENTIFIC ASSESSMENT = drafted by ISA, citation pending.",""]
for sec in ["Biography","Works","Astronomy","Modern assessment"]:
    md+=[f"## {sec}",""]
    for c in d['claims']:
        if c['section']==sec:
            md.append(f"- **{c['id']} [{c['label']}]** {c['text']}  \n  *Sources:* {loc(c)}."+(f" *Note:* {c['note']}" if c['note'] else "")+(f" *Needs:* {c['needs']}" if c['needs'] else ""))
    md.append("")
md+=["## Bibliography (attributed works)","","| ID | Title as recorded in cited sources | Variants | Year | Status | Notes |","|---|---|---|---|---|---|"]
for w in d['works']: md.append(f"| {w['id']} | {w['title']} | {', '.join(w['alt']) or '-'} | {w['year'] or 'unknown'} ({w['yearSource']}) | {w['authorship_status']} | Original-script title not verified; manuscripts: {w['manuscripts']}. {w['notes']} |")
md+=["","## Timeline events (draft)","","| ID | Years | Type | Event | Label | Sources |","|---|---|---|---|---|---|"]
for e in d["events"]: md.append(f"| {e['id']} | {e['year_earliest']}" + (f"–{e['year_latest']}" if e["year_latest"]!=e["year_earliest"] else "") + f" ({e['date_certainty']}) | {e['type']} | {e['title']} | {e['label']} | {loc(e)} |")
md+=["","## Contributions (draft classification)",""]
for c in d['contributions']: md.append(f"- **{c['title']}**: {c['kind']}, attribution confidence {c['confidence']}, {c['label']}. {c['text']}")
md+=["","## Sources and reliability",""]
for s in d['sources']: md.append(f"- **{s['id']}** {s['title']}{' (' + s['author'] + ')' if s['author'] else ''}, {s['publication']}. Read: {'yes' if s['read'] else 'no'}. {s['notes']}")
md+=["","## Open research leads",""]+[f"{i+1}. {l}" for i,l in enumerate(d['leads'])]
md+=["","## What this dossier does not claim","- No total number of works; no claim that he is a mathematician or physicist beyond what S1 says of the astronomical treatises; no direct manuscript or shelfmark inspected; no unverified original-script titles; no day-level dates; no verified teacher list."]
open('docs/ALA_HAZRAT_DOSSIER_DRAFT.md','w',encoding='utf-8').write("\n".join(md)+"\n")
L=["-- DRAFT CONTENT (generated by tools/build_content.py). Loads as status 'draft'. Run once, as an editor/owner, AFTER migrations and seed.sql.","-- It is never visible to the public until it passes the Phase 2/3 publication gate (sources, approved independent review).","do $$ declare sid uuid; cid uuid; wid uuid; eid uuid; srcid uuid; did int; src jsonb:='{}'; begin",
f" insert into scholars(slug,region,period_group,dates_note,status) values ('ahmad-raza-khan','South Asia','modern','1856–1921 CE (project brief; day-level dates unverified)','draft') returning id into sid;",
f" insert into scholar_translations(scholar_id,lang,name) values (sid,'en',{q(d['scholar']['name_en'])});",
" insert into scholar_disciplines(scholar_id,discipline_id) select sid,id from disciplines where name_en='Astronomy';"]
for s in d['sources']:
    if s['id']=='S5': continue
    L.append(f" insert into sources(title,author,publication,url,source_type) values ({q(s['title'])},{q(s['author'])},{q(s['publication'])},{q(s['url'])},{q(s['tier'])}) returning id into srcid; src:=src||jsonb_build_object('{s['id']}',srcid);")
for c in d['contributions']:
    L.append(f" select id into did from disciplines where name_en={q(c['discipline'])};")
    L.append(f" insert into contributions(id,scholar_id,description,title,kind,confidence,discipline_id,period_text,prior_state,detail,label) values ({q(c['id'])},sid,{q(c['text'])},{q(c['title'])},'{c['kind']}','{c['confidence']}',did,{q(c['period'])},{q(c['prior'])},{q(c['detail'])},'under_review');")
    for r in c['refs']: L.append(f" insert into claim_sources(contribution_id,source_id,locator,evidence_tier) values ({q(c['id'])},(src->>'{r['source']}')::uuid,{q(r['locator'])},'{r['tier']}');")
for w in d['works']:
    note=f"Year: {w['year'] or 'unknown'} ({w['yearSource']}). {w['notes']}".strip()
    alts="array["+",".join(q(a) for a in w['alt'])+"]::text[]" if w['alt'] else "null"
    L.append(f" insert into works(scholar_id,original_title,alt_spellings,original_language,subject,authorship_status,publication_note) values (sid,{q(w['title'])},{alts},{q(w['language'])},{q(w['subject'])},'under_review',{q(note)}) returning id into wid;")
    for r in w['sources']: L.append(f" insert into claim_sources(work_id,source_id,locator,evidence_tier) values (wid,(src->>'{r['id']}')::uuid,{q(r['locator'])},'{evidence_tier(r['id'])}');")
for e in d['events']:
    L.append(f" insert into timeline_events(scholar_id,event_type,title,description,year_earliest,year_latest,date_certainty,date_note,confidence,label) values (sid,'{e['type']}',{q(e['title'])},{q(e['description'])},{e['year_earliest']},{e['year_latest']},'{e['date_certainty']}',{q(e['date_note'])},'{e['confidence']}','{e['label'].lower().replace(' ','_')}') returning id into eid;")
    for r in e['sources']: L.append(f" insert into claim_sources(timeline_event_id,source_id,locator,evidence_tier) values (eid,(src->>'{r['id']}')::uuid,{q(r['locator'])},'{evidence_tier(r['id'])}');")
L.append("end $$;")
open('supabase/content/ala_hazrat_draft.sql','w',encoding='utf-8').write("\n".join(L)+"\n")

